3	// Rules 是建立世界时必须满足的规则集合。
4	//
5	// Version 是非空的规则版本；Locations 是允许出现的地点；Edges 描述地点
6	// 之间的连通关系（无向，移动可以沿任一方向发生）；ItemKinds 是允许出现
7	// 的物品种类；CarryLimits 给出每个角色可携带物品的总量上限。
8	type Rules struct {
9		Version     string
10		Locations   []string
11		Edges       []Edge
12		ItemKinds   []string
13		CarryLimits map[string]int
14	}
15	
16	// Edge 表示两个地点之间的一条连通关系。
17	type Edge struct {
18		From string
19		To   string
20	}
21	
22	// CharacterItem 是角色携带的一种物品及其数量。
23	type CharacterItem struct {
24		Item  string
25		Count int
26	}
27	
28	// Character 是一个角色：标识、所在地点和携带物品。
29	type Character struct {
30		ID       string
31		Location string
32		Items    []CharacterItem
33	}
34	
35	// State 是某一时刻世界的完整状态。
36	//
37	// Time 是时间片，世界建立时从零开始，只能向前推进。
38	type State struct {
